"""Example 6: Implement __hash__ and __eq__ correctly."""

class Point:
    """A 2D point — hashable if its components are hashable."""

    def __init__(self, x: int, y: int) -> None:
        self.x = x
        self.y = y

    def __eq__(self, other) -> bool:
        if not isinstance(other, Point):
            return NotImplemented
        return self.x == other.x and self.y == other.y

    def __hash__(self) -> int:
        # Best practice: hash a tuple of the same fields used in __eq__
        return hash((self.x, self.y))

    def __repr__(self) -> str:
        return f"Point({self.x}, {self.y})"

print("=== Using Point as a dict key ===")
d: dict[Point, str] = {}
d[Point(1, 2)] = "origin"
d[Point(3, 4)] = "other"

# Two distinct Point objects with same coords → same key
print(f"  d[Point(1,2)] = {d[Point(1, 2)]}")  # "origin"
print(f"  same key: {Point(1, 2) == Point(1, 2)}")
print(f"  same hash: {hash(Point(1, 2)) == hash(Point(1, 2))}")

print("\n=== Using Point in a set ===")
s = {Point(1, 2), Point(3, 4), Point(1, 2)}  # 3 items, dedup'd to 2
print(f"  set size: {len(s)}")  # 2

print("\n=== The __eq__ without __hash__ trap ===")
class BadPoint:
    def __init__(self, x: int) -> None:
        self.x = x
    def __eq__(self, other) -> bool:
        return isinstance(other, BadPoint) and self.x == other.x
    # No __hash__ defined!

print(f"  BadPoint.__hash__ = {BadPoint.__hash__}")
try:
    d2 = {BadPoint(1): "x"}
except TypeError as e:
    print(f"  TypeError: {e}")
# Defining __eq__ sets __hash__ = None → unhashable.
# Fix: also define __hash__, OR set __hash__ = None explicitly + use only in lists.
```

**The contract:** if `a == b` then `hash(a) == hash(b)`. The reverse is NOT required (collisions are allowed). Break this contract and dicts/sets break in mysterious ways.
